package com.gameaggregator.ledgerservice.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity @Table(name="revenue_transactions") public class RevenueTransaction{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true)public String idempotencyKey;@Column(nullable=false)public UUID clientId;@Column(nullable=false)public UUID gameId;@Column(nullable=false,precision=19,scale=6)public BigDecimal amount;@Column(nullable=false,length=3)public String currency;@Column(nullable=false)public Instant occurredAt;@Column(nullable=false)public Instant recordedAt=Instant.now();protected RevenueTransaction(){}public RevenueTransaction(String i,UUID c,UUID g,BigDecimal a,String u,Instant o){idempotencyKey=i;clientId=c;gameId=g;amount=a;currency=u;occurredAt=o;}}